set selectedDay(day) {
  if (this.mSelectedDayBox) {
    this.mSelectedDayBox.selected = false;
  }

  let realDay = day;
  if (!realDay.isDate) {
    realDay = day.clone();
    realDay.isDate = true;
  }
  const box = this.findDayBoxForDate(realDay);
  if (box) {
    box.selected = true;
    this.mSelectedDayBox = box;
  }
  this.fireEvent("dayselect", realDay);
}

get selectedDay() {
  if (this.mSelectedDayBox) {
    return this.mSelectedDayBox.date.clone();
  }

  return null;
